func (r *Registry) lookup(endpoint string) *bucket {
    // fast path for hot cache
    r.hotMu.RLock()
    if r.hot != nil && endpoint == r.hotName {
        b := r.hot
        r.hotMu.RUnlock()
        return b
    }
    r.hotMu.RUnlock()

    r.mu.Lock()
    b := r.buckets[endpoint]
    if b == nil {
